                self.family = try container.decode(String.self, forKey: .family)
                self.target = try container.decode(String?.self, forKey: .target)
                self.expiresAt = try container.decode(Int64.self, forKey: .expiresAt)
                self.uses = try container.decode(Int64?.self, forKey: .uses)
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encode(self.family, forKey: .family)
                try container.encode(self.target, forKey: .target)
                try container.encode(self.expiresAt, forKey: .expiresAt)
                try container.encode(self.uses, forKey: .uses)
            }

            /// Known values (the member stays a String: a newer daemon may send others).
            public enum Family {
                public static let keys = "keys"
                public static let deviceTrust = "device.trust"
                public static let accountCredentials = "account.credentials"
                public static let identityAdmin = "identity.admin"
                public static let secrets = "secrets"
                public static let settings = "settings"
                public static let dataDestroy = "data.destroy"
                public static let connectorTrust = "connector.trust"
                public static let allValues: [String] = [keys, deviceTrust, accountCredentials, identityAdmin, secrets,
