            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                self.id = container.contains(.id)
                    ? try container.decode(Nullable<Int64>.self, forKey: .id) : nil
                self.name = container.contains(.name)
                    ? try container.decode(Nullable<String>.self, forKey: .name) : nil
                self.email = container.contains(.email)
                    ? try container.decode(Nullable<String>.self, forKey: .email) : nil
                self.role = try container.decodeIfPresent(String.self, forKey: .role)
                self.isActive = container.contains(.isActive)
                    ? try container.decode(Nullable<Bool>.self, forKey: .isActive) : nil
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encodeIfPresent(self.id, forKey: .id)
                try container.encodeIfPresent(self.name, forKey: .name)
                try container.encodeIfPresent(self.email, forKey: .email)
                try container.encodeIfPresent(self.role, forKey: .role)
                try container.encodeIfPresent(self.isActive, forKey: .isActive)
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            public var user: WsModel.User

